// signCommit signs the commit using the registered ObjectSigner plugin.
// If no signer is registered, the commit is left unsigned.
func signCommit(commit *object.Commit) error {
	if !plugin.Has(plugin.ObjectSigner()) {
		return nil
	}

	signer, err := plugin.Get(plugin.ObjectSigner())
	if err != nil {
		return err
	}

	encoded := &plumbing.MemoryObject{}
	if err := commit.EncodeWithoutSignature(encoded); err != nil {
		return err
	}

	r, err := encoded.Reader()
	if err != nil {
		return err
	}

	sig, err := signer.Sign(r)
	if err != nil {
		return err
	}

	commit.Signature = string(sig)
	return nil
}

