// LoadConfig loads a git config for the given scope using the registered
// ConfigLoader plugin. It returns an empty config when the scope cannot
// be loaded (e.g. missing file) and an error only when no ConfigLoader
// plugin has been registered.
func LoadConfig(scope config.Scope) (*config.Config, error) {
	source, err := plugin.Get(plugin.ConfigLoader())
	if err != nil {
		return nil, fmt.Errorf("getting config loader plugin: %w", err)
	}

	storer, err := source.Load(scope)
	if err != nil {
		return config.NewConfig(), nil
	}

	cfg, err := storer.Config()
	if err != nil {
		return config.NewConfig(), nil
	}

	return cfg, nil
}

